mapper.select:
SELECT isch.inbound_schedule_id , stat.name AS status , proc.product_code , proc.name AS product_name , wrhs.warehouse_code , wrhs.name AS warehouse_name , isch.schedule_qty , isch.schedule_date FROM inbound_schedules AS isch JOIN products AS proc ON isch.company_id = proc.company_id AND isch.product_id = proc.product_id JOIN warehouses AS wrhs ON isch.company_id = wrhs.company_id AND isch.warehouse_id = wrhs.warehouse_id LEFT JOIN code_masters AS stat ON stat.code_type = 'INBOUND_STATUS' AND isch.status = stat.code WHERE isch.company_id = #{companyId}
AND isch.status = #{status}
AND proc.product_code LIKE CONCAT('%', #{productCode}, '%')
AND proc.name LIKE CONCAT('%', #{productName}, '%')
AND wrhs.warehouse_code LIKE CONCAT('%', #{warehouseCode}, '%')
AND wrhs.name LIKE CONCAT('%', #{warehouseName}, '%')
ORDER BY isch.inbound_schedule_id;
